(function(){"use strict";async function i(){try{return await(await fetch("/tools.json")).json()}catch(e){return console.error("Failed to load tools database:",e),[]}}function a(e){return`
      <div class="tool-card">
        <div>
          <div class="tool-card-header">
            <div class="tool-icon">${e.icon}</div>
            <div>
              <h3 class="tool-card-title">${e.name}</h3>
            </div>
          </div>
          <p class="tool-card-desc">${e.tagline||e.description}</p>
        </div>
        <div class="tool-card-footer">
          <span class="badge badge-muted">${e.categoryName}</span>
          <a href="${e.url}" class="btn btn-secondary btn-sm">Use Tool &rarr;</a>
        </div>
      </div>
    `}document.addEventListener("DOMContentLoaded",async()=>{const e=await i();if(!e||e.length===0)return;const d=document.querySelector('[data-render-popular="true"]');if(d){const t=e.filter(r=>r.popular);d.innerHTML=t.map(a).join("")}const s=document.querySelector('[data-render-recently-added="true"]');if(s){const t=e.filter(r=>r.recentlyAdded);s.innerHTML=t.map(a).join("")}document.querySelectorAll("[data-render-category]").forEach(t=>{const r=t.getAttribute("data-render-category"),c=e.filter(n=>n.category===r);t.innerHTML=c.map(a).join("")});const o=document.querySelector("[data-render-related]");if(o){const t=o.getAttribute("data-render-related"),r=o.getAttribute("data-current-tool-id"),c=e.filter(n=>n.category===t&&n.id!==r).slice(0,4);o.innerHTML=c.map(a).join("")}})})();
